"""Daily ticker recaps for the user's holdings (generated by the daily-ticker-recap job)."""

from datetime import UTC, date, datetime, timedelta

from connectors.ticker_recap import TickerRecapDto

CADENCE = "daily"
# Older recaps are dropped: covers a long weekend (Friday's recap on Tuesday morning) but not a dead ticker.
MAX_AGE_DAYS = 4


def is_fresh(recap: TickerRecapDto, today: date) -> bool:
    return recap.period_end >= today - timedelta(days=MAX_AGE_DAYS)


def to_json(ticker: str, recap: TickerRecapDto) -> dict:
    created_at = recap.created_at.astimezone(UTC).isoformat().replace("+00:00", "Z") if recap.created_at else None
    return {
        "ticker": ticker,
        "recap": {
            "id": recap.id,
            "period_start": recap.period_start.isoformat(),
            "period_end": recap.period_end.isoformat(),
            "created_at": created_at,
            "summary": recap.summary,
            "bullets": recap.bullets,
            "sources": recap.sources,
        },
    }


def today_utc() -> date:
    return datetime.now(UTC).date()
